// Deadlock Avoidance (C++17)
std::mutex m_a, m_b;
void safe_swap() {
    std::scoped_lock lock(m_a, m_b);
}

std::condition_variable cv;
bool data_ready = false;

void wait_for_data(std::unique_lock<std::mutex>& ul) {
    // Spurious wakeups possible, requires predicate
    cv.wait(ul, []{ return data_ready; });
}

std::atomic<int> lock_free_counter(0);

void update_counter() {
    lock_free_counter.fetch_add(1);
}

// CAS (Compare and Swap)
bool attempt_update(int expected, int desired) {
    return lock_free_counter.compare_exchange_weak(expected, desired);
}

